    properties: {
      lexical: { type: "number" },
      semantic: { type: "number" },
      name_match: { type: "number" },
      kind_boost: { type: "number" },
      file_penalty: { type: "number" },
      importance: { type: "number" },
      proximity: { type: "number" },
      fusion: { type: "number" },
      reranker: { type: "number" },
    },
    required: [
      "lexical",
      "semantic",
      "name_match",
      "kind_boost",
      "file_penalty",
      "importance",
      "proximity",
      "fusion",
      "reranker",
    ],
    title: "SearchSignals",
    type: "object",
